import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void mergeSubarrays(List<Integer> array, int left, int mid, int right) {
        int nLeft = mid - left + 1;
        int nRight = right - mid;
        List<Integer> leftPart = new ArrayList<>(nLeft);
        List<Integer> rightPart = new ArrayList<>(nRight);
        for (int i = 0; i < nLeft; i++) {
            leftPart.add(array.get(left + i));
        }
        for (int j = 0; j < nRight; j++) {
            rightPart.add(array.get(mid + 1 + j));
        }
        int i = 0, j = 0, k = left;
        while (i < nLeft && j < nRight) {
            if (leftPart.get(i) <= rightPart.get(j)) {
                array.set(k++, leftPart.get(i++));
            } else {
                array.set(k++, rightPart.get(j++));
            }
        }
        while (i < nLeft) {
            array.set(k++, leftPart.get(i++));
        }
        while (j < nRight) {
            array.set(k++, rightPart.get(j++));
        }
    }

    public static void sortArray(List<Integer> array, int start, int end) {
        if (start < end) {
            int mid = start + (end - start) / 2;
            sortArray(array, start, mid);
            sortArray(array, mid + 1, end);
            mergeSubarrays(array, start, mid, end);
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        List<Integer> v = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            v.add(scanner.nextInt());
        }
        sortArray(v, 0, n - 1);
        if (n == 1) {
            System.out.println(v.get(0));
        } else {
            int midIdx = n / 2;
            System.out.println(v.get(midIdx));
        }
        scanner.close();
    }
}
